function staffShell(content){const nav=staffRole==='Super Admin'?[['dashboard','Dashboard'],['departments','Departments'],['hods','HOD Management'],['students','Students'],['faculty','Faculty'],['questions','Questions'],['cycles','Feedback Cycles'],['analytics','Analytics'],['exports','Downloads'],['audit','Audit Log'],['settings','Settings']]:[['dashboard','Dashboard'],['faculty','Faculty'],['cycles','Feedback Cycles'],['analytics','Analytics'],['exports','Downloads']];return `<div class="portal-shell"><aside class="sidebar"><div class="brand-row"><img src="data:image/png;base64," class="sidebar-astra-logo" alt="ASTRA"><div><b>ASTRA</b><small>SIDDHANT COE</small></div></div><div class="role-pill"><b>${esc(profile?.full_name||'Staff')}</b><br>${esc(staffRole)}</div><div class="nav">${nav.map(([k,l])=>`<button class="${currentStaffPage===k?'active':''}" onclick="staffPage('${k}')">${l}</button>`).join('')}</div><div class="side-bottom"><button class="nav button" style="background:rgba(255,255,255,.08);color:#fff" onclick="signOut()">Sign out</button></div></aside><main class="main"><div class="topbar"><div class="brandline topbar-brand"><img src="data:image/png;base64," alt="Siddhant College of Engineering"><span>Siddhant College of Engineering · ASTRA Feedback Intelligence</span></div><div class="topbar-actions"><button class="btn secondary" onclick="refreshStaff()">Refresh</button></div></div><div id="staffContent">${content}</div></main></div>`}
